{"content":"import { createFileRoute, Link } from "@tanstack/react-router";
import { BRANDS, CATEGORIES, PRODUCTS, formatPrice } from "@/data/catalog";
import { useStore } from "@/lib/store";
import { useAccess } from "@/hooks/useAccess";

export const Route = createFileRoute("/admin")({
  head: () => ({
    meta: [
      { title: "Staff Dashboard | Pickrel Brothers Inc." },
      {
        name: "description",
        content:
          "Internal Pickrel Brothers dashboard for reviewing catalog coverage, incoming quote requests and recent orders.",
      },
      { name: "robots", content: "noindex" },
      { property: "og:title", content: "Staff Dashboard | Pickrel Brothers Inc." },
      { property: "og:description", content: "Internal catalog, quote and order overview." },
    ],
  }),
  component: AdminPage,
});

function AdminPage() {
  const { orders, quotes } = useStore();
  const access = useAccess();

  if (access.loading) {
    return <div className="container-page py-16 text-center text-muted-foreground">Loading…</div>;
  }

  if (!access.isAdmin) {
    return (
      <div className="container-page py-16 text-center">
        <h1 className="font-display text-3xl font-bold uppercase text-navy">Admin access only</h1>
        <p className="mt-3 text-muted-foreground">
          {access.user
            ? "This account doesn't have admin access."
            : "Sign in with a Pickrel Brothers admin account to view this dashboard."}
        </p>
        <Link
          to="/auth"
          className="mt-6 inline-block rounded-md bg-navy px-6 py-3 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted"
        >
          Go to sign in
        </Link>
      </div>
    );
  }

  const outOfStock = PRODUCTS.filter((p) => p.availability === "special-order").length;

  return (
    <div className="container-page py-10">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="font-display text-3xl font-bold uppercase text-navy">Admin Dashboard</h1>
          <p className="mt-1 text-sm text-muted-foreground">Signed in as {access.user?.email} · Admin</p>
        </div>
        <div className="flex flex-wrap gap-3">
          <Link
            to="/"
            className="rounded-md border border-input px-5 py-2.5 font-display font-bold uppercase tracking-wide text-navy hover:bg-secondary"
          >
            View customer storefront
          </Link>
          <Link
            to="/admin/pricing"
            className="rounded-md bg-navy px-5 py-2.5 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted"
          >
            Pricing console
          </Link>
        </div>
      </div>


      <div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <Stat label="Products listed" value={String(PRODUCTS.length)} />
        <Stat label="Categories" value={String(CATEGORIES.length)} />
        <Stat label="Manufacturers" value={String(BRANDS.length)} />
        <Stat label="Special-order items" value={String(outOfStock)} />
      </div>

      <div className="mt-8 grid gap-8 lg:grid-cols-2">
        <section className="rounded-md border border-border bg-card shadow-card">
          <h2 className="border-b border-border px-5 py-3 font-display text-lg font-bold uppercase text-navy">
            Quote requests
          </h2>
          {quotes.length === 0 ? (
            <p className="px-5 py-8 text-sm text-muted-foreground">No quote requests submitted yet.</p>
          ) : (
            <ul className="divide-y divide-border">
              {quotes.map((q) => (
                <li key={q.id} className="flex items-center justify-between gap-3 px-5 py-4">
                  <div>
                    <p className="font-mono text-sm font-semibold text-foreground">{q.id}</p>
                    <p className="text-xs text-muted-foreground">
                      {q.jobName} · {q.items.length} items ·{" "}
                      {new Date(q.createdAt).toLocaleDateString()}
                    </p>
                  </div>
                  <span className="rounded-full bg-sky-soft px-3 py-1 text-xs font-semibold text-navy">
                    {q.status}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </section>

        <section className="rounded-md border border-border bg-card shadow-card">
          <h2 className="border-b border-border px-5 py-3 font-display text-lg font-bold uppercase text-navy">
            Recent orders
          </h2>
          {orders.length === 0 ? (
            <p className="px-5 py-8 text-sm text-muted-foreground">No orders submitted yet.</p>
          ) : (
            <ul className="divide-y divide-border">
              {orders.map((o) => (
                <li key={o.id} className="flex items-center justify-between gap-3 px-5 py-4">
                  <div>
                    <p className="font-mono text-sm font-semibold text-foreground">{o.id}</p>
                    <p className="text-xs text-muted-foreground">
                      PO {o.poNumber} · {new Date(o.createdAt).toLocaleDateString()} · {o.status}
                    </p>
                  </div>
                  <span className="text-sm font-semibold text-foreground">{formatPrice(o.total)}</span>
                </li>
              ))}
            </ul>
          )}
        </section>
      </div>

      <section className="mt-8 rounded-md border border-border bg-card p-6 shadow-card">
        <h2 className="font-display text-lg font-bold uppercase text-navy">Catalog coverage by category</h2>
        <ul className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {CATEGORIES.map((c) => {
            const count = PRODUCTS.filter((p) => p.category === c.slug).length;
            return (
              <li
                key={c.slug}
                className="flex items-center justify-between rounded-md border border-border px-4 py-2 text-sm"
              >
                <span className="text-foreground">{c.name}</span>
                <span className="font-semibold text-sky">{count}</span>
              </li>
            );
          })}
        </ul>
        <p className="mt-4 text-xs text-muted-foreground">
          Demo dashboard. Product, pricing and order data will come from the ERP feed once connected.
        </p>
      </section>
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-md border border-border bg-card p-5 shadow-card">
      <p className="font-display text-3xl font-bold text-navy">{value}</p>
      <p className="mt-1 text-xs font-semibold uppercase tracking-wide text-muted-foreground">{label}</p>
    </div>
  );
}
